solution.code:
function fibMemo(n, memo = new Map()) {
  if (n <= 1) return n;
  if (memo.has(n)) return memo.get(n);
  const result = fibMemo(n-1, memo) + fibMemo(n-2, memo);
  memo.set(n, result);
  return result;
}

function coinChangeMemo(coins, amount, memo = new Map()) {
  if (amount === 0) return 0;
  if (amount < 0) return Infinity;
  if (memo.has(amount)) return memo.get(amount);
  let min = Infinity;
  for (const coin of coins) {
    const sub = coinChangeMemo(coins, amount - coin, memo);
    if (sub !== Infinity) min = Math.min(min, 1 + sub);
  }
  memo.set(amount, min);
  return min;
}

function uniquePathsMemo(m, n, memo = new Map()) {
  const key = `${m},${n}`;
  if (m === 1 || n === 1) return 1;
  if (memo.has(key)) return memo.get(key);
  const result = uniquePathsMemo(m-1, n, memo) + uniquePathsMemo(m, n-1, memo);
  memo.set(key, result);
  return result;
}

