solution.code:
function climbStairsImpl(n) {
  if (n <= 2) return n;
  let prev2 = 1, prev1 = 2;
  for (let i = 3; i <= n; i++) {
    const curr = prev1 + prev2;
    prev2 = prev1;
    prev1 = curr;
  }
  return prev1;
}

function minCostClimbingStairsImpl(cost) {
  const n = cost.length;
  const dp = new Array(n + 1).fill(0);
  for (let i = 2; i <= n; i++) {
    dp[i] = Math.min(dp[i-1] + cost[i-1], dp[i-2] + cost[i-2]);
  }
  return dp[n];
}

function numDecodingsImpl(s) {
  const n = s.length;
  if (s[0] === '0') return 0;
  const dp = new Array(n + 1).fill(0);
  dp[0] = 1;
  dp[1] = 1;
  for (let i = 2; i <= n; i++) {
    if (s[i-1] !== '0') dp[i] += dp[i-1];
    const twoDigit = Number(s.slice(i-2, i));
    if (twoDigit >= 10 && twoDigit <= 26) dp[i] += dp[i-2];
  }
  return dp[n];
}

