solution.code:
function robImpl(nums) {
  if (nums.length === 1) return nums[0];
  let prev2 = nums[0];
  let prev1 = Math.max(nums[0], nums[1]);
  for (let i = 2; i < nums.length; i++) {
    const curr = Math.max(prev1, prev2 + nums[i]);
    prev2 = prev1;
    prev1 = curr;
  }
  return prev1;
}

function rob2Impl(nums) {
  if (nums.length === 1) return nums[0];
  if (nums.length === 2) return Math.max(nums[0], nums[1]);
  function linearRob(arr) {
    let prev2 = arr[0], prev1 = Math.max(arr[0], arr[1]);
    for (let i = 2; i < arr.length; i++) {
      const curr = Math.max(prev1, prev2 + arr[i]);
      prev2 = prev1; prev1 = curr;
    }
    return prev1;
  }
  return Math.max(
    linearRob(nums.slice(0, nums.length - 1)),
    linearRob(nums.slice(1))
  );
}

