solution.code:
function longestPalindromeImpl(s) {
  let start = 0, maxLen = 1;
  function expand(l, r) {
    while (l >= 0 && r < s.length && s[l] === s[r]) {
      if (r - l + 1 > maxLen) { maxLen = r - l + 1; start = l; }
      l--; r++;
    }
  }
  for (let i = 0; i < s.length; i++) { expand(i, i); expand(i, i+1); }
  return s.slice(start, start + maxLen);
}

function countSubstringsImpl(s) {
  let count = 0;
  function expand(l, r) {
    while (l >= 0 && r < s.length && s[l] === s[r]) { count++; l--; r++; }
  }
  for (let i = 0; i < s.length; i++) { expand(i, i); expand(i, i+1); }
  return count;
}

function longestPalindromeDPImpl(s) {
  const n = s.length;
  const dp = Array.from({length:n}, () => new Array(n).fill(false));
  let start = 0, maxLen = 1;
  for (let i = 0; i < n; i++) dp[i][i] = true;
  for (let i = 0; i < n-1; i++) {
    if (s[i] === s[i+1]) { dp[i][i+1] = true; start = i; maxLen = 2; }
  }
  for (let len = 3; len <= n; len++) {
    for (let i = 0; i <= n - len; i++) {
      const j = i + len - 1;
      if (s[i] === s[j] && dp[i+1][j-1]) {
        dp[i][j] = true;
        if (len > maxLen) { maxLen = len; start = i; }
      }
    }
  }
  return s.slice(start, start + maxLen);
}
